function todaysActivity(){const today=dateKey();return state.activity.filter(x=>x.day===today)}
function memberToday(name){const rows=todaysActivity().filter(x=>x.actor===name);return{calls:Math.max(0,rows.filter(x=>x.kind==='call').length-rows.filter(x=>x.kind==='call_undo').length),followups:Math.max(0,rows.filter(x=>x.kind==='followup').length-rows.filter(x=>x.kind==='followup_undo').length),leads:new Set(rows.filter(x=>['call','call_undo','followup','followup_undo','lead_status','lead_added'].includes(x.kind)).map(x=>x.subject)).size,tasks:rows.filter(x=>x.kind==='task_completed').length}}
function activityLabel(item){if(item.kind==='break_started')return `${esc(item.actor)} started a break`;if(item.kind==='break_ended')return `${esc(item.actor)} ended a break`;if(item.kind==='session_started')return `${esc(item.actor)} started a work session`;if(item.kind==='session_ended')return `${esc(item.actor)} ended a work session${item.detail?` (${esc(item.detail)})`:''}`;if(item.kind==='login')return `${esc(item.actor)} signed in`;if(item.kind==='logout')return `${esc(item.actor)} signed out`;const actions={call:'logged a cold call for',call_undo:'corrected a cold call count for',followup:'logged a follow-up for',followup_undo:'corrected a follow-up count for',lead_status:'updated status for',lead_added:'added',task_completed:'completed',task_updated:'updated task',task_assigned:'assigned task',imported:'imported'};const detail=item.kind==='task_completed'?'':item.detail;return `${esc(item.actor)} ${actions[item.kind]||'updated'} ${esc(item.subject)}${detail?` · ${esc(detail)}`:''}` }function activityTime(item){return new Date(item.at).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})}
function dailyActivityRows(){return ['Mohamed Ahnaf','Jeeva','Lalu'].map(name=>{const m=memberToday(name);const active=state.leads.filter(l=>l.owner===name).length;return `<tr><td><div class="lead-cell">${avatar(name)}<span>${esc(name)}</span></div></td><td>${m.calls}</td><td>${m.followups}</td><td>${m.leads}</td><td>${m.tasks}</td><td>${active}</td></tr>`}).join('')}
function dailyOverviewStats(){const members=['Mohamed Ahnaf','Jeeva','Lalu'].map(memberToday);const totals=members.reduce((a,m)=>({calls:a.calls+m.calls,followups:a.followups+m.followups,leads:a.leads+m.leads,tasks:a.tasks+m.tasks}),{calls:0,followups:0,leads:0,tasks:0});return `<div class="stat-grid"><div class="stat-card"><div class="stat-label">Calls logged today</div><div class="stat-number">${totals.calls}</div><div class="stat-meta">Across the team</div></div><div class="stat-card"><div class="stat-label">Follow-ups today</div><div class="stat-number">${totals.followups}</div><div class="stat-meta">Across the team</div></div><div class="stat-card"><div class="stat-label">Leads updated today</div><div class="stat-number">${totals.leads}</div><div class="stat-meta">Unique leads touched</div></div><div class="stat-card"><div class="stat-label">Tasks completed today</div><div class="stat-number">${totals.tasks}</div><div class="stat-meta">Across the team</div></div></div>`}
function stats(){const calls=state.leads.reduce((n,l)=>n+(Number(l.calls)||0),0),due=state.leads.filter(l=>l.status==='Follow-up').length,qualified=state.leads.filter(l=>['Qualified','Approved'].includes(l.status)).length;return `<div class="stat-grid"><div class="stat-card"><div class="stat-label">Total prospects <span class="stat-symbol">◉</span></div><div class="stat-number">${state.leads.length.toLocaleString()}</div><div class="stat-meta">In the lead tracker</div></div><div class="stat-card"><div class="stat-label">Cold calls logged <span class="stat-symbol">⌕</span></div><div class="stat-number">${calls}</div><div class="stat-meta">Across tracked prospects</div></div><div class="stat-card"><div class="stat-label">Follow-up prospects <span class="stat-symbol">↻</span></div><div class="stat-number">${due}</div><div class="stat-meta">Currently marked follow-up</div></div><div class="stat-card"><div class="stat-label">Qualified leads <span class="stat-symbol">✳</span></div><div class="stat-number">${qualified}</div><div class="stat-meta">Qualified or approved</div></div></div>`}function workspaceSummary(){const openTasks=state.tasks.filter(t=>t.state!=='Done').length,followups=state.leads.filter(l=>l.status==='Follow-up').length,qualified=state.leads.filter(l=>['Qualified','Approved'].includes(l.status)).length;return `<div class="stat-grid overall-stat-grid"><div class="stat-card"><div class="stat-label">Total leads</div><div class="stat-number">${state.leads.length}</div><div class="stat-meta">Across all employees</div></div><div class="stat-card"><div class="stat-label">Open tasks</div><div class="stat-number">${openTasks}</div><div class="stat-meta">Not marked complete</div></div><div class="stat-card"><div class="stat-label">Follow-up pipeline</div><div class="stat-number">${followups}</div><div class="stat-meta">Currently needing contact</div></div><div class="stat-card"><div class="stat-label">Qualified leads</div><div class="stat-number">${qualified}</div><div class="stat-meta">Qualified or approved</div></div></div>`}
function myAttendancePanel(){const a=attendanceSummary(state.userName),status=a.onBreak?'On break':a.working?'Working now':a.rows.length?'Session ended':'Not started';return `<section class="panel attendance-self"><div class="panel-head"><div><div class="panel-title">My attendance today</div><div class="panel-subtitle">Start, end, work time, and breaks recorded for today</div></div><span class="attendance-status ${a.onBreak?'on-break':a.working?'is-working':''}">${status}</span></div><div class="attendance-self-stats"><div><small>First start</small><b>${a.firstLogin}</b></div><div><small>Session timer</small><b>${sessionTimerMarkup(a)}</b></div><div><small>Break time</small><b data-break-hours="${esc(state.userName)}">${a.breakHours}</b></div><div><small>Hours worked</small><b data-work-hours="${esc(state.userName)}">${a.hours}</b></div></div><div class="attendance-session-list">${a.rows.map(row=>`<div class="attendance-session"><span>Started ${new Date(row.loginAt).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'})}</span><span>${row.logoutAt?'Ended '+new Date(row.logoutAt).toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'}):a.onBreak?'On break':'Session active'} · Break ${formatHours(breakDurationFor(row))}</span><b>${formatHours(sessionWorkDuration(row))} worked</b></div>`).join('')||'<div class="empty-state">No work session started today. Use Start work session when you begin.</div>'}</div></section>`}function attendancePanel(){return `<section class="panel recent-panel" style="margin-top:15px"><div class="panel-head"><div><div class="panel-title">Today’s attendance and work hours</div><div class="panel-subtitle">Current work status, session times, and cumulative breaks for the team</div></div></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>First start</th><th>Last end</th><th>Status</th><th>Break time</th><th>Hours worked</th><th>Sessions</th></tr></thead><tbody>${attendanceRows()}</tbody></table></div></section>`}function overview(){return `${header(`Good morning, ${esc(state.userName.split(' ')[0])} 👋`,'Here is your Absze team overview for today.',`${workToggleButton()}<button class="button-primary" data-action="new-task"><span class="plus">+</span> Assign task</button>`)}${dailyOverviewStats()}${workspaceSummary()}<section class="panel recent-panel"><div class="panel-head"><div><div class="panel-title">Today’s team activity</div><div class="panel-subtitle">Work logged by each employee today</div></div><button class="text-link" data-page="team">Full team view →</button></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Calls</th><th>Follow-ups</th><th>Leads updated</th><th>Tasks completed</th><th>Assigned leads</th></tr></thead><tbody>${dailyActivityRows()}</tbody></table></div></section><section class="panel recent-panel" style="margin-top:15px"><div class="panel-head"><div><div class="panel-title">Recent team updates</div><div class="panel-subtitle">Live activity recorded in this workspace</div></div></div><div class="activity-feed">${todaysActivity().slice(0,8).map(x=>`<div class="feed-item"><span class="feed-dot"></span><div><b>${activityLabel(x)}</b><small>${activityTime(x)}</small></div></div>`).join('')||'<div class="empty-state"><b>No updates yet today</b>Employee calls, follow-ups, lead changes, and completed tasks will appear here.</div>'}</div></section>${attendancePanel()}`}function leadsPage(){const assigned=state.role==='employee'?state.leads.filter(l=>l.owner===state.userName):state.leads;let filtered=assigned.filter(l=>(state.filter==='All leads'||l.status===state.filter)&&(!state.query||Object.values(l).join(' ').toLowerCase().includes(state.query.toLowerCase())));const actions=`<button class="button-secondary" data-action="import">⇧&nbsp; Import data</button><button class="button-secondary" data-action="new-lead">＋ Manual add</button><button class="button-primary" data-action="add-user"><span class="plus">+</span> Add user${state.staged.length?` · ${state.staged.length}`:''}</button>`;return `${header(state.role==='employee'?'My leads':'Lead tracker',state.role==='employee'?'Your assigned prospects and outreach follow-ups.':'Imported names stay in Imports until you choose a status and add them here.',actions)}${state.staged.length?`<div class="pending-strip"><span><b>${state.staged.length} imported name${state.staged.length===1?'':'s'}</b> ready to add</span><button class="text-link" data-action="add-user">Choose a name →</button></div>`:''}<div class="stat-grid"><div class="stat-card"><div class="stat-label">${state.role==='employee'?'My leads':'All leads'}</div><div class="stat-number">${assigned.length}</div><div class="stat-meta">${state.role==='employee'?'Assigned to you':'In your workspace'}</div></div><div class="stat-card"><div class="stat-label">Follow-ups</div><div class="stat-number">${assigned.filter(x=>x.status==='Follow-up').length}</div><div class="stat-meta">Need another touch</div></div><div class="stat-card"><div class="stat-label">Approved</div><div class="stat-number">${assigned.filter(x=>x.status==='Approved'||x.status==='Qualified').length}</div><div class="stat-meta">Ready for next steps</div></div><div class="stat-card"><div class="stat-label">Cold calls logged</div><div class="stat-number">${assigned.reduce((a,x)=>a+(+x.calls||0),0)}</div><div class="stat-meta">${state.role==='employee'?'Your activity':'Across tracked leads'}</div></div></div><div class="filter-row">${['All leads','New','Contacted','Follow-up','Cold call','Qualified','Approved','Closed'].map(x=>`<button class="filter-chip ${state.filter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}<input class="toolbar-search" id="leadSearch" placeholder="⌕  Search prospects" value="${esc(state.query)}"></div><section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>Prospect</th><th>Company</th><th>Email</th><th>Phone</th><th>Status</th><th>Assigned to</th><th>Cold calls</th><th>Follow-ups</th><th>Last activity</th></tr></thead><tbody>${filtered.length?leadRows(filtered):'<tr><td colspan="9"><div class="empty-state"><b>No matching prospects</b>Try a different search or status.</div></td></tr>'}</tbody></table></div><div class="table-footer">Showing ${filtered.length} of ${assigned.length} prospects</div></section>`}
function employeeDashboard(){const mine=state.leads.filter(l=>l.owner===state.userName);const tasks=state.tasks.filter(t=>t.owner===state.userName);const calls=mine.reduce((a,x)=>a+(+x.calls||0),0);const followUps=mine.reduce((a,x)=>a+(+x.followUps||0),0);const pending=tasks.filter(t=>t.state!=='Done');const shift=attendanceSummary(state.userName);return `${header(`Good morning, ${esc(state.userName.split(' ')[0])} 👋`,'Your assigned work and today’s attendance.',`${workToggleButton()}`)}<div class="stat-grid"><div class="stat-card"><div class="stat-label">My leads <span class="stat-symbol">◉</span></div><div class="stat-number">${mine.length}</div><div class="stat-meta">Assigned to you</div></div><div class="stat-card"><div class="stat-label">Cold calls <span class="stat-symbol">⌕</span></div><div class="stat-number">${calls}</div><div class="stat-meta">Logged on your leads</div></div><div class="stat-card"><div class="stat-label">Follow-ups <span class="stat-symbol">↻</span></div><div class="stat-number">${followUps}</div><div class="stat-meta">Logged on your leads</div></div><div class="stat-card"><div class="stat-label">Open tasks <span class="stat-symbol">✓</span></div><div class="stat-number">${pending.length}</div><div class="stat-meta">Assigned to you</div></div></div>${myAttendancePanel()}<div class="overview-grid"><section class="panel"><div class="panel-head"><div><div class="panel-title">My assigned tasks</div><div class="panel-subtitle">Work assigned to you</div></div><button class="text-link" data-page="tasks">View all →</button></div><div class="mini-goals">${pending.slice(0,4).map(t=>`<div class="mini-goal"><div><b>${esc(t.title)}</b><span style="display:block;margin-top:4px">${esc(t.tag)} · Due ${esc(t.due)}</span></div><select class="select-status" data-task="${state.tasks.indexOf(t)}"><option ${t.state==='To do'?'selected':''}>To do</option><option ${t.state==='In progress'?'selected':''}>In progress</option><option ${t.state==='Done'?'selected':''}>Done</option></select></div>`).join('')||'<div class="empty-state"><b>You’re all caught up</b>No open tasks assigned to you.</div>'}</div></section><section class="panel goal-panel"><div class="panel-head"><div><div class="panel-title">My qualified leads</div><div class="panel-subtitle">Current status across prospects assigned to you</div></div></div><div class="goal-hero"><div class="goal-caption">Qualified or approved</div><div class="goal-value"><strong>${mine.filter(x=>x.status==='Qualified'||x.status==='Approved').length}</strong><span>assigned to you</span></div><div class="goal-foot"><span>Check My goals for configured team targets.</span></div></div></section></div><section class="panel recent-panel"><div class="panel-head"><div><div class="panel-title">My recent leads</div><div class="panel-subtitle">Update status or log a cold call and follow-up</div></div><button class="text-link" data-page="leads">View my leads →</button></div><div class="table-wrap"><table><thead><tr><th>Prospect</th><th>Company</th><th>Email</th><th>Phone</th><th>Status</th><th>Assigned to</th><th>Cold calls</th><th>Follow-ups</th><th>Last activity</th></tr></thead><tbody>${mine.length?leadRows(mine.slice(0,5)):'<tr><td colspan="9"><div class="empty-state"><b>No leads assigned yet</b>Ask your admin to assign prospects to you.</div></td></tr>'}</tbody></table></div></section>`}function tasksPage(){let cols=['To do','In progress','Done'];const visibleTasks=state.role==='employee'?state.tasks.filter(t=>t.owner===state.userName):state.tasks;const taskHeader=state.role==='employee'?header('My tasks','Tasks assigned to you. Update the status as work moves forward.'):header('Tasks','Assign work, make ownership clear, and keep the team on track.',`<button class="button-primary" data-action="new-task"><span class="plus">+</span> Assign task</button>`);return `${taskHeader}<div class="task-grid">${cols.map(c=>`<section class="task-column"><div class="column-head">${c}<span class="column-count">${visibleTasks.filter(t=>t.state===c).length}</span></div>${visibleTasks.filter(t=>t.state===c).map(t=>`<article class="task-card"><span class="task-tag">${esc(t.tag)}</span><h3>${esc(t.title)}</h3><p>${esc(t.desc)}</p><div class="task-foot"><div class="task-person">${avatar(t.owner)}${esc(t.owner)}</div><span class="${t.due==='Today'?'overdue':''}">◷ ${esc(t.due)}</span><select class="select-status" data-task="${state.tasks.indexOf(t)}"><option ${t.state==='To do'?'selected':''}>To do</option><option ${t.state==='In progress'?'selected':''}>In progress</option><option ${t.state==='Done'?'selected':''}>Done</option></select></div></article>`).join('')||'<div class="task-card" style="color:#a0aaa6;font-size:9px;text-align:center">No tasks here yet</div>'}</section>`).join('')}</div>`}
function importsPage(){return `${header('Imports','Upload scraped data here. Imported names move into Lead Tracker only after you choose a status.',`<button class="button-primary" data-action="import"><span class="plus">+</span> Import data</button>`)}<div class="import-layout"><section class="panel"><div class="panel-head"><div><div class="panel-title">Import prospects</div><div class="panel-subtitle">Upload Excel, PDF, Word, PowerPoint, CSV, or text files to stage names for review</div></div></div><div class="dropzone" id="dropzone"><div class="upload-icon">⇧</div><b>Drop a supported file here, or <span>browse</span></b><p>Imported records will wait for review before entering your lead tracker</p><span>Choose a file</span></div><div class="import-requirements"><b>Supported:</b> Excel (.xlsx, .xls), PDF, Word (.docx), PowerPoint (.pptx), OpenDocument (.ods, .odt, .odp), RTF, CSV, TSV, and TXT. Include a Name column and, when available, company, email, and phone. Max 10MB.</div></section><section class="panel"><div class="panel-head"><div><div class="panel-title">Recent imports</div><div class="panel-subtitle">Your team’s import history</div></div></div><div class="import-history">${state.imports.map(x=>`<div class="import-item"><div class="file-icon">▤</div><div class="import-info"><b>${esc(x.file)}</b><span>${esc(x.date)} · ${esc(x.by)}</span></div><div class="import-count">+${x.count} names</div></div>`).join('')||'<div class="empty-state">No imports yet</div>'}</div><div class="import-note">Duplicates are skipped. Choose a status for each name in Lead Tracker → Add user.</div></section></div><section class="panel" style="margin-top:15px"><div class="panel-head"><div><div class="panel-title">Names waiting for review</div><div class="panel-subtitle">Only names are shown here. Choose a status when adding someone to the tracker.</div></div><button class="text-link" data-page="leads">Open Lead Tracker →</button></div>${state.staged.length?`<div class="staged-name-list">${state.staged.map(x=>`<div class="staged-name">${esc(x.name)}</div>`).join('')}</div>`:'<div class="empty-state"><b>No imported names waiting</b>Import a supported file to stage prospects here.</div>'}</section>`}
function goalsPage(){const personal=state.role==='employee';const goals=state.customGoals.filter(g=>!personal||g.owner===state.userName||g.owner==='Absze team');const cards=goals.map(g=>{const leads=g.owner==='Absze team'?state.leads:state.leads.filter(l=>l.owner===g.owner);const current=g.metric==='Qualified prospects'?leads.filter(l=>['Qualified','Approved'].includes(l.status)).length:g.metric==='Calls completed'?leads.reduce((n,l)=>n+(+l.calls||0),0):g.metric==='Follow-ups closed'?leads.reduce((n,l)=>n+(+l.followUps||0),0):g.metric==='New prospects sourced'?leads.length:0;const target=Math.max(1,+g.target||1),progress=Math.min(100,Math.round(current/target*100));return `<article class="panel goal-card"><div class="goal-card-top"><div><h3>${esc(g.name)}</h3><p>${esc(g.owner)} · ${esc(g.metric)}</p></div><span class="goal-badge">${esc(g.due||'No due date')}</span></div><div class="goal-value"><strong>${current}</strong><span>of ${target}</span></div><div class="progress-track"><div class="progress-fill" style="width:${progress}%"></div></div><div class="goal-card-foot"><span>Progress</span><span>${progress}%</span></div></article>`}).join('');return `${header(personal?'My goals':'Goals',personal?'Team goals assigned to you and your progress.':'Create targets for the team or an individual employee.',personal?'':`<button class="button-primary" data-action="new-goal"><span class="plus">+</span> Create goal</button>`)}<div class="goal-grid">${cards||'<section class="panel empty-state"><b>No goals set yet</b>Create a goal to start tracking progress here.</section>'}</div>`}function tourSteps(){return state.role==='admin'?[{page:'overview',title:'Admin dashboard',text:'Review company totals, today’s calls and follow-ups, each employee’s updates, and attendance hours.'},{page:'leads',title:'Lead tracker',text:'Review imported prospects, assign them, choose their status, and use plus or minus to log or correct calls and follow-ups.'},{page:'imports',title:'Imports',text:'Upload a supported file. Names wait here until you choose a status and add them to the lead tracker.'},{page:'tasks',title:'Tasks',text:'Assign work to an employee, set a due date, and follow completion from the team dashboard.'},{page:'goals',title:'Goals',text:'Track current team results against targets and create additional goals.'},{page:'team',title:'Team performance',text:'Compare each employee’s daily calls, follow-ups, lead updates, completed tasks, and work hours.'},{page:'settings',title:'Settings and notifications',text:'Manage workspace notifications and change your account password.'}]:[{page:'employee',title:'My dashboard',text:'See your assigned work, today’s logged activity, and the hours in your current work session.'},{page:'leads',title:'My leads',text:'Update lead status and log calls or follow-ups. Use minus to undo an accidental count.'},{page:'imports',title:'Imports',text:'Upload a supported file and review names before adding them to your assigned leads.'},{page:'tasks',title:'My tasks',text:'Review your assigned work and update a task to Done when you finish it.'},{page:'goals',title:'My goals',text:'Check your current results against the team’s targets.'},{page:'settings',title:'Settings and notifications',text:'Manage notifications and change your account password.'}]}
function showTourStep(index){const steps=tourSteps();if(index>=steps.length){document.querySelector('.tour-backdrop')?.remove();toast('Tour complete');return}const step=steps[index];state.tourIndex=index;setPage(step.page);let wrap=document.querySelector('.tour-backdrop');if(!wrap){wrap=document.createElement('div');wrap.className='tour-backdrop';document.body.append(wrap)}wrap.innerHTML=`<section class="tour-modal" role="dialog" aria-modal="true" aria-labelledby="tourTitle"><button class="tour-close" type="button" aria-label="Close tour">×</button><span class="tour-kicker">ABSZE WORKSPACE TOUR · ${index+1} OF ${steps.length}</span><h2 id="tourTitle">${esc(step.title)}</h2><p>${esc(step.text)}</p><div class="tour-progress">${steps.map((_,i)=>`<i class="${i<=index?'active':''}"></i>`).join('')}</div><div class="tour-actions"><button type="button" class="button-secondary" data-tour-prev ${index===0?'disabled':''}>Back</button><button type="button" class="button-secondary" data-tour-exit>Exit tour</button><button type="button" class="button-primary" data-tour-next>${index===steps.length-1?'Finish':'Next'}</button></div></section>`;wrap.querySelector('.tour-close').onclick=()=>wrap.remove();wrap.querySelector('[data-tour-exit]').onclick=()=>wrap.remove();wrap.querySelector('[data-tour-prev]').onclick=()=>showTourStep(index-1);wrap.querySelector('[data-tour-next]').onclick=()=>showTourStep(index+1)}
function startTour(){showTourStep(0)}function settingsPage(){return `${header('Settings','Manage your account, password, and notification preferences.',`<button class="button-primary" data-action="save-settings">Save changes</button>`)}<div class="settings-grid"><section class="panel settings-card"><div class="panel-head"><div><div class="panel-title">Your account</div><div class="panel-subtitle">Signed-in Absze workspace account</div></div></div><div class="settings-fields"><div class="field"><label>Name</label><input value="${esc(state.userName)}" disabled></div><div class="field"><label>Work email</label><input value="${esc(state.userEmail)}" disabled></div><div class="field"><label>Workspace name</label><input id="settingsWorkspace" value="${esc(state.settings.workspaceName||'Absze')}" ${state.role==='employee'?'disabled':''}></div></div></section><section class="panel settings-card"><div class="panel-head"><div><div class="panel-title">Change password</div><div class="panel-subtitle">Choose a new password for your account</div></div></div><form class="settings-fields password-settings-form" id="passwordChangeForm"><div class="field"><label for="currentPassword">Current password</label><input id="currentPassword" name="currentPassword" type="password" autocomplete="current-password" required></div><div class="field"><label for="newPassword">New password</label><input id="newPassword" name="newPassword" type="password" autocomplete="new-password" minlength="10" required></div><div class="field"><label for="confirmPassword">Confirm new password</label><input id="confirmPassword" name="confirmPassword" type="password" autocomplete="new-password" minlength="10" required></div><button class="button-secondary" type="submit">Update password</button><p class="settings-note">Use at least 10 characters. ${firebaseAuthEnabled()?'This updates your Firebase account.':'Prototype password changes stay in this browser.'}</p></form></section><section class="panel settings-card"><div class="panel-head"><div><div class="panel-title">Notifications</div><div class="panel-subtitle">In-app alerts shown from the bell in the top bar</div></div></div><div class="settings-fields"><label class="setting-toggle"><span><b>In-app notifications</b><small>Show relevant alerts in this workspace</small></span><input id="notifyAll" type="checkbox" ${state.settings.notifications?'checked':''}></label><label class="setting-toggle"><span><b>Follow-up reminders</b><small>Alert me when leads need another touch</small></span><input id="notifyFollowups" type="checkbox" ${state.settings.followups?'checked':''}></label><label class="setting-toggle"><span><b>Task reminders</b><small>Alert me about tasks due today</small></span><input id="notifyTasks" type="checkbox" ${state.settings.tasks?'checked':''}></label><p class="settings-note">In-app reminders are shown in Absze. Admin device alerts require Firebase team sharing to be connected.</p></div></section><section class="panel settings-card" data-role="admin"><div class="panel-head"><div><div class="panel-title">Team activity alerts</div><div class="panel-subtitle">Sign-in, work session, and break notifications</div></div></div><div class="settings-fields"><button class="button-secondary notification-enable" id="enableDesktopNotifications" type="button">Enable notifications on this device</button><b id="desktopNotificationsStatus" class="notification-status"></b><p class="settings-note">Enable this separately on each laptop or phone. Keep the Absze workspace open and connected for live alerts. Your browser may need permission, and mobile alerts depend on its notification settings.</p></div></section><section class="panel settings-card" data-role="admin"><div class="panel-head"><div><div class="panel-title">Team data sharing</div><div class="panel-subtitle">Firebase connection</div></div></div><div class="settings-fields"><b id="syncStatus">${esc(syncStatusMessage)}</b><p class="settings-note">Configure Firebase in <code>firebase-config.js</code> to sync team records and use Firebase email/password sign-in across devices.</p></div></section></div>`}function saveSettings(){state.settings.workspaceName=state.role==='admin'?($('#settingsWorkspace').value.trim()||'Absze'):state.settings.workspaceName;state.settings.notifications=$('#notifyAll').checked;state.settings.followups=$('#notifyFollowups').checked;state.settings.tasks=$('#notifyTasks').checked;save();render();toast('Settings saved')}function openNotifications(){const mine=state.role==='employee'?state.leads.filter(l=>l.owner===state.userName):state.leads;const myTasks=state.role==='employee'?state.tasks.filter(t=>t.owner===state.userName):state.tasks;const notices=[];if(state.settings.notifications){if(state.settings.followups){const due=mine.filter(l=>l.status==='Follow-up');if(due.length)notices.push(`<div class="notice-item"><span class="notice-mark">↻</span><div><b>${due.length} follow-up${due.length===1?'':'s'} to review</b><small>Leads waiting for another touch</small></div><button type="button" class="text-link" data-go-page="leads">Open leads →</button></div>`)}if(state.settings.tasks){const due=myTasks.filter(t=>t.state!=='Done'&&t.due==='Today');if(due.length)notices.push(`<div class="notice-item"><span class="notice-mark">✓</span><div><b>${due.length} task${due.length===1?'':'s'} due today</b><small>Assigned work to keep moving</small></div><button type="button" class="text-link" data-go-page="tasks">Open tasks →</button></div>`)}if(state.staged.length)notices.push(`<div class="notice-item"><span class="notice-mark">⇧</span><div><b>${state.staged.length} imported name${state.staged.length===1?'':'s'} waiting</b><small>Choose a status before adding them</small></div><button type="button" class="text-link" data-go-page="imports">Open imports →</button></div>`)}const wrap=modal('Notifications',state.settings.notifications?'Your current workspace reminders.':'In-app notifications are turned off in Settings.',notices.length?`<div class="notice-list">${notices.join('')}</div>`:'<div class="empty-state"><b>You’re all caught up</b>No notifications to show right now.</div>','Close',()=>{});wrap.querySelectorAll('[data-go-page]').forEach(b=>b.onclick=()=>{const page=b.dataset.goPage;wrap.remove();setPage(page)})}
function openProfile(){const a=attendanceSummary(state.userName),active=!!a.activeSession,status=a.onBreak?'On break':a.working?'Working now':'Not working';const wrap=modal('Your profile',`${esc(state.userEmail)} · ${state.role==='admin'?'Workspace admin':'Employee'}`,`<div class="profile-card-modal"><div class="profile-avatar">${initials(state.userName)}</div><div><b>${esc(state.userName)}</b><small>${esc(state.userEmail)} · ${status}</small></div></div><div class="profile-menu-actions"><button type="button" class="button-outline" data-profile-shift>${active?'End work session':'Start work session'}</button><button type="button" class="button-secondary" data-profile-settings>Settings</button><button type="button" class="button-secondary" data-profile-signout>Sign out</button></div>`,'Close',()=>{});wrap.querySelector('[data-profile-settings]').onclick=()=>{wrap.remove();setPage('settings')};wrap.querySelector('[data-profile-signout]').onclick=()=>{wrap.remove();signOut()};wrap.querySelector('[data-profile-shift]').onclick=()=>{wrap.remove();toggleWorkSession()}}function toggleWorkSession(){const active=!!attendanceSummary(state.userName).activeSession;if(active){endAttendance();recordActivity('session_ended',state.userName)}else{startAttendance();recordActivity('session_started',state.userName)}save();render();toast(active?'Work session ended':'Work session started')}function teamRows(){return ['Mohamed Ahnaf','Jeeva','Lalu'].map((name,i)=>{const mine=state.leads.filter(l=>l.owner===name),calls=mine.reduce((n,l)=>n+(Number(l.calls)||0),0),followups=mine.reduce((n,l)=>n+(Number(l.followUps)||0),0),qualified=mine.filter(l=>['Qualified','Approved'].includes(l.status)).length,target=Number(state.customGoals.find(g=>g.owner===name&&g.metric==='Qualified prospects')?.target)||0,progress=target?Math.min(100,Math.round(qualified/target*100)):0;return `<tr><td><div class="lead-cell">${avatar(name,['coral','blue','lavender'][i])}<span>${esc(name)}</span></div></td><td class="team-metric">${calls}</td><td>${followups}</td><td>${qualified}</td><td>${target?`${progress}% <span class="performance-bar"><i style="width:${progress}%"></i></span>`:'No goal set'}</td><td>${state.tasks.filter(t=>t.owner===name&&t.state!=='Done').length} open tasks</td></tr>`}).join('')}function teamPage(){return `${header('Team performance','Today’s progress and current workload for the Absze team.',`${workToggleButton()}<span class="range-label">${new Date().toLocaleDateString('en-IN',{weekday:'long',month:'long',day:'numeric'})}</span>`)}${dailyOverviewStats()}<section class="panel team-table"><div class="panel-head"><div><div class="panel-title">Employee activity today</div><div class="panel-subtitle">Daily updates are recorded when employees use their tracker</div></div></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Calls</th><th>Follow-ups</th><th>Leads updated</th><th>Tasks completed</th><th>Assigned leads</th></tr></thead><tbody>${dailyActivityRows()}</tbody></table></div></section><section class="panel recent-panel" style="margin-top:15px"><div class="panel-head"><div><div class="panel-title">Recent updates</div><div class="panel-subtitle">Latest activity across the team</div></div></div><div class="activity-feed">${todaysActivity().slice(0,15).map(x=>`<div class="feed-item"><span class="feed-dot"></span><div><b>${activityLabel(x)}</b><small>${activityTime(x)}</small></div></div>`).join('')||'<div class="empty-state"><b>No updates yet today</b>Employee activity will appear here as it happens.</div>'}</div></section>${attendancePanel()}<section class="panel team-table" style="margin-top:15px"><div class="panel-head"><div><div class="panel-title">Overall workload</div><div class="panel-subtitle">Current totals across each employee’s assigned leads</div></div></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Cold calls</th><th>Follow-ups</th><th>Qualified</th><th>Goal progress</th><th>Open tasks</th></tr></thead><tbody>${teamRows()}</tbody></table></div></section>`}function render(){const pages={overview,employee:employeeDashboard,leads:leadsPage,tasks:tasksPage,imports:importsPage,goals:goalsPage,settings:settingsPage,team:teamPage};content.innerHTML=(pages[state.page]||overview)();document.querySelectorAll('.nav-item').forEach(n=>{n.hidden=(n.dataset.role==='admin'&&state.role!=='admin')||(n.dataset.role==='employee'&&state.role!=='employee')||(n.dataset.page==='overview'&&state.role==='employee')||(n.dataset.page==='employee'&&state.role==='admin');n.classList.toggle('active',n.dataset.page===state.page);const copy=n.querySelector('.nav-copy');if(copy)copy.textContent=({overview:'Overview',employee:'My dashboard',leads:state.role==='employee'?'My leads':'Lead tracker',tasks:state.role==='employee'?'My tasks':'Tasks',imports:'Imports',goals:state.role==='employee'?'My goals':'Goals',settings:'Settings',team:'Team performance'})[n.dataset.page]||copy.textContent});document.querySelectorAll('[data-role=admin]:not(.nav-item)').forEach(n=>n.hidden=state.role!=='admin');$('#workspaceName').textContent=state.settings.workspaceName||'Absze';$('#profileInitials').textContent=initials(state.userName);$('#topProfileButton').textContent=initials(state.userName);$('#crumbPage').textContent=({overview:'Overview',employee:'My dashboard',leads:state.role==='employee'?'My leads':'Lead tracker',tasks:state.role==='employee'?'My tasks':'Tasks',imports:'Imports',goals:state.role==='employee'?'My goals':'Goals',settings:'Settings',team:'Team performance'})[state.page]||'Overview';$('#leadNavCount').textContent=state.role==='employee'?state.leads.filter(l=>l.owner===state.userName).length:state.leads.length;$('#taskNavCount').textContent=state.tasks.filter(t=>t.state!=='Done'&&(state.role!=='employee'||t.owner===state.userName)).length;$('#profileName').textContent=state.userName;$('#profileRole').textContent=state.role==='admin'?'Workspace admin':'Employee';bindPage()}
function closeMobileNav(){document.querySelector('.sidebar').classList.remove('open');$('#mobileMenu').setAttribute('aria-expanded','false')}function setPage(p){if(state.role==='employee'&&['overview','team'].includes(p))p='employee';if(state.role==='admin'&&p==='employee')p='overview';state.page=p;state.query='';render();closeMobileNav()}
function toast(s){let t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2600)}
function modal(title,desc,body,submitText,callback){let wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<section class="modal"><div class="modal-head"><div><h2>${title}</h2><p>${desc}</p></div><button class="modal-close" aria-label="Close">×</button></div><form id="modalForm">${body}<div class="modal-actions"><button type="button" class="button-secondary modal-cancel">Cancel</button><button class="button-primary" type="submit">${submitText}</button></div></form></section>`;document.body.append(wrap);wrap.querySelector('.modal-close').onclick=()=>wrap.remove();wrap.querySelector('.modal-cancel').onclick=()=>wrap.remove();wrap.onclick=e=>{if(e.target===wrap)wrap.remove()};wrap.querySelector('form').onsubmit=e=>{e.preventDefault();callback(new FormData(e.target));wrap.remove()};return wrap}
function openStagedPicker(){if(!state.staged.length){toast('Import a supported file first. Its names will appear here.');setPage('imports');return}let wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.innerHTML=`<section class="modal"><div class="modal-head"><div><h2>Add an imported user</h2><p>Choose a name to review and set a status before adding it.</p></div><button class="modal-close" aria-label="Close">×</button></div><div class="staged-picker">${state.staged.map(item=>`<button class="staged-person" type="button" data-pick-user="${esc(item.id)}"><span class="staged-person-avatar">${initials(item.name)}</span><span>${esc(item.name)}</span><b>›</b></button>`).join('')}</div><div class="modal-actions"><button type="button" class="button-secondary modal-cancel">Close</button></div></section>`;document.body.append(wrap);wrap.querySelector('.modal-close').onclick=()=>wrap.remove();wrap.querySelector('.modal-cancel').onclick=()=>wrap.remove();wrap.onclick=e=>{if(e.target===wrap)wrap.remove()};wrap.querySelectorAll('[data-pick-user]').forEach(b=>b.onclick=()=>{const id=b.dataset.pickUser;wrap.remove();openStagedStatus(id)})}
function openStagedStatus(id){const item=state.staged.find(x=>x.id===id);if(!item)return;modal('Set status for '+esc(item.name),'Select a status before this person is added to the Lead Tracker.',`<div class="selected-person"><span class="staged-person-avatar">${initials(item.name)}</span><b>${esc(item.name)}</b></div><div class="form-grid"><div class="field full"><label>Status *</label><select name="status" required><option>Follow-up</option><option>Cold call</option><option>Closed</option><option>Approved</option><option>New</option><option>Contacted</option><option>Qualified</option></select></div>${state.role==='admin'?`<div class="field full"><label>Assign to</label><select name="owner"><option>Mohamed Ahnaf</option><option>Jeeva</option><option>Lalu</option><option>Unassigned</option></select></div>`:`<input type="hidden" name="owner" value="${esc(state.userName)}"><div class="field full"><label>Assigned to</label><div class="selected-person">${esc(state.userName)}</div></div>`}</div>`,`Add to Lead Tracker`,f=>{state.staged=state.staged.filter(x=>x.id!==id);state.leads.unshift({...item,status:f.get('status'),owner:state.role==='employee'?state.userName:f.get('owner'),last:item.last&&item.last!=='—'?item.last:'Today'});recordActivity('lead_added',item.name,'Added with status '+f.get('status'));save();render();toast(item.name+' added to Lead Tracker')})}
function openLead(){modal('Add a prospect','Create a lead and assign it to a teammate.',`<div class="form-grid"><div class="field"><label>Name *</label><input name="name" required placeholder="Jamie Parker"></div><div class="field"><label>Company</label><input name="company" placeholder="Company name"></div><div class="field"><label>Email</label><input name="email" type="email" placeholder="jamie@company.com"></div><div class="field"><label>Phone</label><input name="phone" placeholder="+1 (555) 010-0000"></div><div class="field"><label>Status</label><select name="status"><option>New</option><option>Contacted</option><option>Follow-up</option><option>Qualified</option><option>Cold call</option><option>Closed</option><option>Approved</option><option>Cold</option></select></div><div class="field"><label>Assign to</label><select name="owner"><option>Mohamed Ahnaf</option><option>Jeeva</option><option>Lalu</option><option>Unassigned</option></select></div></div>`,`Add prospect`,f=>{state.leads.unshift({name:f.get('name'),company:f.get('company'),email:f.get('email'),phone:f.get('phone'),status:f.get('status'),owner:state.role==='employee'?state.userName:f.get('owner'),calls:0,followUps:0,last:'Today',source:'Manual'});recordActivity('lead_added',f.get('name'),'Added to lead tracker');save();render();toast('Prospect added to your tracker')})}
function openTask(){modal('Assign a task','Give a teammate clear ownership and a due date.',`<div class="form-grid"><div class="field full"><label>Task title *</label><input name="title" required placeholder="e.g. Follow up with new prospects"></div><div class="field full"><label>Details</label><textarea name="desc" placeholder="Add a note about what needs to happen"></textarea></div><div class="field"><label>Assign to</label><select name="owner"><option>Mohamed Ahnaf</option><option>Jeeva</option><option>Lalu</option></select></div><div class="field"><label>Due</label><select name="due"><option>Today</option><option>Tomorrow</option><option>This week</option><option>Next week</option></select></div><div class="field"><label>Category</label><select name="tag"><option>FOLLOW-UP</option><option>COLD CALL</option><option>LEAD REVIEW</option><option>MEETING</option><option>DATA</option></select></div><div class="field"><label>Status</label><select name="state"><option>To do</option><option>In progress</option></select></div></div>`,`Assign task`,f=>{state.tasks.unshift({title:f.get('title'),desc:f.get('desc'),owner:f.get('owner'),due:f.get('due'),tag:f.get('tag'),state:f.get('state')});recordActivity('task_assigned',f.get('title'),'Assigned to '+f.get('owner'));save();render();toast('Task assigned successfully')})}
function openGoal(){modal('Create a team goal','Set a target that the whole team can work toward.',`<div class="form-grid"><div class="field full"><label>Goal name *</label><input name="name" required placeholder="e.g. Qualified prospects"></div><div class="field"><label>Target number</label><input name="target" type="number" min="1" required placeholder="100"></div><div class="field"><label>Metric</label><select name="metric"><option>Qualified prospects</option><option>Calls completed</option><option>Follow-ups closed</option><option>New prospects sourced</option></select></div><div class="field"><label>Owner</label><select name="owner"><option>Absze team</option><option>Mohamed Ahnaf</option><option>Jeeva</option><option>Lalu</option></select></div><div class="field"><label>Due date</label><input name="due" type="date"></div></div>`,`Create goal`,f=>{state.customGoals.unshift({name:f.get('name'),target:+f.get('target'),metric:f.get('metric'),owner:f.get('owner'),due:f.get('due')});save();render();toast('Goal created')})}
function bindPage(){document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>setPage(b.dataset.page));document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>setPage(b.dataset.page));content.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>({ 'new-lead':openLead,'add-user':openStagedPicker,'new-task':openTask,'new-goal':openGoal,'save-settings':saveSettings,'import':()=>$('#csvInput').click(),'export':exportCsv,'toggle-shift':toggleWorkSession,'start-break':startBreak,'end-break':endBreak}[b.dataset.action]||(()=>{}))());content.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render()});content.querySelectorAll('[data-log]').forEach(b=>b.onclick=()=>{const l=state.leads[+b.dataset.lead];l[b.dataset.log]=(Number(l[b.dataset.log])||0)+1;l.last='Today';recordActivity(b.dataset.log==='calls'?'call':'followup',l.name);save();render();toast(b.dataset.log==='calls'?'Cold call logged':'Follow-up logged')});content.querySelectorAll('[data-undo]').forEach(b=>b.onclick=()=>{const l=state.leads[+b.dataset.lead];const key=b.dataset.undo;l[key]=Math.max(0,(Number(l[key])||0)-1);l.last='Today';recordActivity(key==='calls'?'call_undo':'followup_undo',l.name);save();render();toast(key==='calls'?'Cold call count corrected':'Follow-up count corrected')});content.querySelectorAll('[data-status]').forEach(s=>s.onchange=()=>{let lead=state.leads[+s.dataset.status];lead.status=s.value;lead.last='Today';recordActivity('lead_status',lead.name,'Changed status to '+s.value);save();render();toast('Prospect status updated')});content.querySelectorAll('[data-task]').forEach(s=>s.onchange=()=>{const task=state.tasks[+s.dataset.task],wasDone=task.state==='Done';task.state=s.value;recordActivity(!wasDone&&task.state==='Done'?'task_completed':'task_updated',task.title,task.state==='Done'?'Completed':'Status: '+task.state);save();render();toast('Task status updated')});const passwordForm=$('#passwordChangeForm');if(passwordForm)passwordForm.onsubmit=changePassword;const enableNotifications=$('#enableDesktopNotifications');if(enableNotifications)enableNotifications.onclick=enableDeviceNotifications;const notificationStatus=$('#desktopNotificationsStatus');if(notificationStatus)notificationStatus.textContent=deviceNotificationStatus();const tourButton=$('#startTourButton');if(tourButton)tourButton.onclick=startTour;const search=$('#leadSearch');if(search)search.oninput=()=>{const pos=search.selectionStart;state.query=search.value;const y=window.scrollY;render();const next=$('#leadSearch');next.focus();next.setSelectionRange(pos,pos);window.scrollTo(0,y)};const dz=$('#dropzone');if(dz){dz.onclick=()=>$('#csvInput').click();dz.ondragover=e=>{e.preventDefault();dz.style.borderColor='#4e957a'};dz.ondragleave=()=>dz.style.borderColor='';dz.ondrop=e=>{e.preventDefault();dz.style.borderColor='';if(e.dataTransfer.files[0])handleFile(e.dataTransfer.files[0])}}}
function parseCSV(text){let rows=[],row=[],cell='',q=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'&&q&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')q=!q;else if((c===','||c==='\t')&&!q){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(rows.length<2)return[];let headers=rows.shift().map(h=>h.trim().toLowerCase().replace(/[\s_-]+/g,''));return rows.map(r=>Object.fromEntries(headers.map((h,i)=>[h,(r[i]||'').trim()])))}
function loadParser(kind){const globalName=kind==='xlsx'?'XLSX':'officeParser';if(window[globalName])return Promise.resolve(window[globalName]);if(parserLoads[kind])return parserLoads[kind];parserLoads[kind]=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=parserUrls[kind];script.async=true;script.onload=()=>window[globalName]?resolve(window[globalName]):reject(new Error('The file reader did not initialize. Refresh the page and try again.'));script.onerror=()=>reject(new Error('Could not load the file reader. Connect to the internet, refresh, and try again.'));document.head.append(script)});return parserLoads[kind]}
function officeHeader(value){return String(value||'').trim().toLowerCase().replace(/[^a-z0-9]/g,'')}
function officeTextRecords(text,allowNames=false){const lines=String(text||'').replace(/\u00a0/g,' ').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);const splitLine=line=>line.includes('\t')?line.split(/\t+/).map(x=>x.trim()).filter(Boolean):line.includes('|')?line.split('|').map(x=>x.trim()).filter(Boolean):/\s{2,}/.test(line)?line.split(/\s{2,}/).map(x=>x.trim()).filter(Boolean):[line];const rows=lines.map(splitLine);const aliases=new Set(['name','fullname','leadname','prospectname','contactname','firstname','first','lastname','last','email','emailaddress','company','companyname','organization','phone','phonenumber','mobile','owner','assignee','status','source','calls','coldcalls','followups','followupcount']);let headerIndex=rows.findIndex(cells=>cells.some(c=>aliases.has(officeHeader(c)))&&(cells.length>1||['name','fullname','leadname','prospectname','contactname'].includes(officeHeader(cells[0]))));if(headerIndex>=0){const headers=rows[headerIndex].map(officeHeader);return rows.slice(headerIndex+1).filter(cells=>cells.length>1||headers.length===1).map(cells=>Object.fromEntries(headers.map((h,i)=>[h,cells[i]||'']))).filter(row=>Object.values(row).some(Boolean))}const emailRows=[];for(const line of lines){const match=line.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);if(!match)continue;const before=line.slice(0,match.index).trim().replace(/[|,;\-–]+$/,'').trim();const after=line.slice(match.index+match[0].length).trim();const name=before.split(/[|,;\t]+/).map(x=>x.trim()).filter(Boolean)[0]||before.split(/\s+/).slice(0,2).join(' ');emailRows.push({name,email:match[0],company:after.split(/[|,;\t]+/).map(x=>x.trim()).filter(Boolean)[0]||''})}if(emailRows.length)return emailRows;if(allowNames){const skip=new Set(['name','names','prospect','prospects','contact','contacts','lead','leads','sales leads','customer list']);return lines.map(x=>x.replace(/^(?:[-*•]|\d+[.)])\s*/, '').trim()).filter(x=>x.length<65&&/^[\p{L}][\p{L}'’.-]+(?:\s+[\p{L}][\p{L}'’.-]+){1,4}$/u.test(x)&&!skip.has(x.toLowerCase())).map(name=>({name}))}return[]}
async function readImportedFile(file){const ext=file.name.split('.').pop().toLowerCase();if(['csv','tsv'].includes(ext))return parseCSV(await file.text());if(ext==='txt'){const text=await file.text();if(text.includes('\t')||text.includes(','))return parseCSV(text);return officeTextRecords(text,true)}if(['xlsx','xls','xlsb'].includes(ext)){const XLSX=await loadParser('xlsx');const workbook=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false});return workbook.SheetNames.flatMap(sheet=>XLSX.utils.sheet_to_json(workbook.Sheets[sheet],{defval:'',raw:false}).map(row=>Object.fromEntries(Object.entries(row).map(([k,v])=>[officeHeader(k),String(v??'')]))))}if(['pdf','docx','pptx','odt','ods','odp','rtf'].includes(ext)){const officeParser=await loadParser('office');const ast=await officeParser.parseOffice(file);const output=await ast.to('text',{includeImages:false,textConfig:{preserveLayout:false,renderNotes:false}});return officeTextRecords(output.value,ext==='docx'||ext==='pptx'||ext==='odt'||ext==='odp'||ext==='rtf')}throw new Error('Unsupported format. Use Excel, PDF, Word, PowerPoint, OpenDocument, RTF, CSV, TSV, or TXT.')}
async function handleFile(file){if(file.size>10*1024*1024){toast('File is larger than 10MB');return}const ext=file.name.split('.').pop().toLowerCase();const accepted=['csv','tsv','txt','xlsx','xls','xlsb','pdf','docx','pptx','odt','ods','odp','rtf'];if(!accepted.includes(ext)){toast('Unsupported format. Try XLS/XLSX, PDF, DOCX, PPTX, ODT/ODS/ODP, RTF, CSV, TSV, or TXT.');return}toast('Reading '+file.name+'…');try{const records=await readImportedFile(file);let added=0;const seen=new Set([...state.leads,...state.staged].map(x=>(x.email||'').toLowerCase()).filter(Boolean));const key=(r,...ks)=>{for(const k of ks){const v=r[officeHeader(k)];if(v!==undefined&&String(v).trim())return String(v).trim()}return''};records.forEach(r=>{const email=key(r,'email','emailaddress').toLowerCase();const name=key(r,'name','fullname','leadname','prospectname','contactname')||[key(r,'firstname','first'),key(r,'lastname','last')].filter(Boolean).join(' ');if(!name||(email&&seen.has(email)))return;if(email)seen.add(email);state.staged.unshift({id:crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`,name,company:key(r,'company','companyname','organization'),email,phone:key(r,'phone','phonenumber','mobile'),owner:key(r,'owner','assignee')||'Unassigned',calls:+key(r,'coldcalls','calls','callcount')||0,followUps:+key(r,'followups','followupcount')||0,last:key(r,'lastactivity','lastcontacted')||'—',source:key(r,'source')||file.name});added++});if(!added){const scanned=ext==='pdf'?' This PDF may be scanned; text-based PDFs work best.':'';toast('No names were found. Include a Name column or a clear list of names.'+scanned);return}state.imports.unshift({file:file.name,count:added,date:new Date().toLocaleDateString('en-IN',{month:'short',day:'numeric',year:'numeric'}),by:state.userName});recordActivity('imported',file.name,added+' names staged');save();render();toast(`${added} name${added===1?'':'s'} imported. Add them from Lead Tracker → Add user.`)}catch(error){toast(error.message||'Could not read this file. Try saving it as XLSX, DOCX, PPTX, or PDF.')}}
function exportCsv(){let header=['name','company','email','phone','status','owner','calls','last_activity','source'];let lines=[header.join(','),...state.leads.map(l=>header.map(h=>{let val=l[h]||l[h.replace('_','')]||'';return '"'+String(val).replace(/"/g,'""')+'"'}).join(','))];let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/csv'}));a.download='absze-prospects.csv';a.click();URL.revokeObjectURL(a.href);toast('Prospects exported as CSV')}
$('#loginForm').onsubmit=handleLogin;$('#toggleLoginPassword').onclick=()=>{const field=$('#loginPassword'),show=field.type==='password';field.type=show?'text':'password';$('#toggleLoginPassword').textContent=show?'Hide':'Show'};$('#refreshCaptcha').onclick=refreshCaptcha;$('#csvInput').onchange=e=>{if(e.target.files[0])handleFile(e.target.files[0]);e.target.value=''};$('#mobileMenu').onclick=()=>{const open=$('.sidebar').classList.toggle('open');$('#mobileMenu').setAttribute('aria-expanded',String(open))};$('#closeMobileMenu').onclick=closeMobileNav;$('#profileMenu').onclick=openProfile;$('#topProfileButton').onclick=openProfile;$('#notificationsButton').onclick=openNotifications;$('#searchButton').onclick=()=>{setPage('leads');setTimeout(()=>$('#leadSearch')?.focus(),20)};window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#searchButton').click()}if(e.key==='Escape'){document.querySelector('.modal-backdrop')?.remove();closeMobileNav()}});
window.addEventListener('storage',e=>{if(!e.key||e.key.startsWith('northstar_')){const read=(key,fallback)=>JSON.parse(localStorage.getItem(key)||'null')??fallback;state.leads=read('northstar_leads',[]);state.tasks=read('northstar_tasks',[]);state.customGoals=read('northstar_goals',[]);state.activity=read('northstar_activity',[]);state.attendance=read('northstar_attendance',[]);state.settings=read('northstar_settings',{workspaceName:'Absze',notifications:true,followups:true,tasks:true});state.staged=read('northstar_staged',[]);state.imports=read('northstar_imports',[]);render()}});setInterval(()=>{document.querySelectorAll('[data-session-timer]').forEach(el=>{const base=Number(el.dataset.timerBaseMs)||0,started=Number(el.dataset.timerRenderedAt)||Date.now(),elapsed=base+Math.max(0,Date.now()-started);el.textContent=`${el.dataset.timerMode==='break'?'Break':'Work'} ${formatTimer(elapsed)}`});document.querySelectorAll('[data-work-hours]').forEach(el=>el.textContent=attendanceSummary(el.dataset.workHours).hours);document.querySelectorAll('[data-break-hours]').forEach(el=>el.textContent=attendanceSummary(el.dataset.breakHours).breakHours)},1000);

